import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p92_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor exclusive_cumsum_cuda(torch::Tensor x, int64_t dim);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("exclusive_cumsum", &exclusive_cumsum_cuda, "Exclusive cumulative sum (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

#define TILE_SIZE 1024

// Pass 1: Each block scans a tile of TILE_SIZE elements within one row.
// Writes local exclusive scan into out[], and the tile's total sum into block_sums[].
__global__ void exclusive_scan_pass1(
    const float* __restrict__ in,
    float* __restrict__ out,
    float* __restrict__ block_sums,
    int row_len,
    int num_blocks_per_row
) {
    __shared__ float sdata[TILE_SIZE];

    int row   = blockIdx.x;
    int tile  = blockIdx.y;  // which tile within the row
    int tid   = threadIdx.x;
    int global_idx = row * row_len + tile * TILE_SIZE + tid;

    // Load tile into shared memory
    float val = (tile * TILE_SIZE + tid < row_len) ? in[global_idx] : 0.0f;
    sdata[tid] = val;
    __syncthreads();

    // Inclusive scan in shared memory (Kogge-Stone)
    for (int stride = 1; stride < TILE_SIZE; stride <<= 1) {
        float tmp = (tid >= stride) ? sdata[tid - stride] : 0.0f;
        __syncthreads();
        sdata[tid] += tmp;
        __syncthreads();
    }

    // sdata[tid] is now inclusive prefix sum; convert to exclusive by shifting
    float excl = (tid > 0) ? sdata[tid - 1] : 0.0f;
    if (tile * TILE_SIZE + tid < row_len)
        out[global_idx] = excl;

    // Write tile aggregate (last inclusive value) to block_sums
    if (tid == TILE_SIZE - 1) {
        block_sums[row * num_blocks_per_row + tile] = sdata[TILE_SIZE - 1];
    }
    __syncthreads();
}

// Pass 2: For each row, compute exclusive prefix sum of block_sums in a single warp,
// then add the offset into the corresponding tile's output.
__global__ void exclusive_scan_pass2(
    float* __restrict__ out,
    const float* __restrict__ block_sums,
    int row_len,
    int num_blocks_per_row
) {
    // one block per row; threads handle tiles
    int row = blockIdx.x;
    int tid = threadIdx.x;

    // Each thread processes one tile offset
    // First: compute exclusive scan of block_sums for this row using shared mem
    extern __shared__ float soffsets[];

    if (tid < num_blocks_per_row)
        soffsets[tid] = block_sums[row * num_blocks_per_row + tid];
    else
        soffsets[tid] = 0.0f;
    __syncthreads();

    // Kogge-Stone inclusive scan over tile sums
    for (int stride = 1; stride < num_blocks_per_row; stride <<= 1) {
        float tmp = (tid >= stride && tid < num_blocks_per_row) ? soffsets[tid - stride] : 0.0f;
        __syncthreads();
        if (tid < num_blocks_per_row)
            soffsets[tid] += tmp;
        __syncthreads();
    }

    // soffsets[tid] is inclusive; exclusive offset for tile tid is soffsets[tid-1]
    float tile_offset = (tid > 0 && tid < num_blocks_per_row) ? soffsets[tid - 1] : 0.0f;

    if (tid < num_blocks_per_row && tile_offset != 0.0f) {
        int tile_start = row * row_len + tid * TILE_SIZE;
        int tile_end   = min(tile_start + TILE_SIZE, row * row_len + row_len);
        for (int i = tile_start; i < tile_end; i++) {
            out[i] += tile_offset;
        }
    }
}

torch::Tensor exclusive_cumsum_cuda(torch::Tensor x, int64_t dim) {
    // Fast path: contiguous float32 CUDA tensor, last dimension
    int64_t ndim = x.dim();
    int64_t norm_dim = (dim < 0) ? dim + ndim : dim;

    bool fast_path = x.is_cuda()
        && x.scalar_type() == torch::kFloat32
        && x.is_contiguous()
        && norm_dim == ndim - 1
        && x.size(norm_dim) > 1;

    if (!fast_path) {
        // Fallback
        auto cumsum = torch::cumsum(x.narrow(dim, 0, x.size(dim) - 1), dim);
        return torch::cat({torch::zeros_like(x.select(dim, 0).unsqueeze(dim)), cumsum}, dim);
    }

    int64_t row_len = x.size(norm_dim);
    int64_t num_rows = x.numel() / row_len;

    int num_blocks_per_row = (int)((row_len + TILE_SIZE - 1) / TILE_SIZE);

    auto out = torch::empty_like(x);
    auto block_sums = torch::zeros({num_rows, num_blocks_per_row}, x.options());

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // Pass 1
    dim3 grid1((int)num_rows, num_blocks_per_row);
    dim3 block1(TILE_SIZE);
    exclusive_scan_pass1<<<grid1, block1, 0, stream>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        block_sums.data_ptr<float>(),
        (int)row_len,
        num_blocks_per_row
    );

    // Pass 2: one block per row, num_blocks_per_row threads
    // shared memory: num_blocks_per_row floats
    int pass2_threads = 1;
    while (pass2_threads < num_blocks_per_row) pass2_threads <<= 1;
    size_t smem = pass2_threads * sizeof(float);
    dim3 grid2((int)num_rows);
    dim3 block2(pass2_threads);
    exclusive_scan_pass2<<<grid2, block2, smem, stream>>>(
        out.data_ptr<float>(),
        block_sums.data_ptr<float>(),
        (int)row_len,
        num_blocks_per_row
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs an exclusive cumulative sum (does not include the current element).

        Parameters:
            dim (int): The dimension along which to perform the exclusive cumulative sum.
        """
    def __init__(self, dim):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Fast path via custom CUDA two-pass blocked scan
                ext = _stark_get_extension()
                ndim = x.dim()
                norm_dim = self.dim if self.dim >= 0 else self.dim + ndim
                if (x.is_cuda and x.dtype == torch.float32 and x.is_contiguous()
                        and norm_dim == ndim - 1 and x.size(norm_dim) > 1):
                    return ext.exclusive_cumsum(x, self.dim)
                # Fallback for non-contiguous / non-last-dim / non-float32
                cumsum = torch.cumsum(x.narrow(dim=self.dim, start=0, length=x.size(self.dim)-1), dim=self.dim)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return torch.cat((torch.zeros_like(x.select(self.dim, 0).unsqueeze(self.dim)), cumsum), dim=self.dim)
        # <<<END_IMPROVE>>>

