#define BLOCK_SIZE 1024
#define WARP_SIZE 32

__device__ __forceinline__ float warp_scan_inclusive(float val) {
    #pragma unroll
    for (int offset = 1; offset < WARP_SIZE; offset *= 2) {
        float temp = __shfl_up_sync(0xFFFFFFFF, val, offset);
